101:     applyTheme(theme) {
102:       window.BibleState.theme = theme;
103:       document.documentElement.setAttribute('data-theme', theme);
104:       localStorage.setItem('church_bible_theme', theme);
105:       const themeBtn = document.getElementById('btn-theme-toggle');
106:       if (themeBtn) {
107:         themeBtn.textContent = theme === 'dark' ? '☀️' : '🌙';
108:         themeBtn.title = theme === 'dark' ? 'Switch to Light Theme' : 'Switch to Dark Theme';
109:       }
110:     }
111: 
112:     toggleTheme() {
113:       const next = window.BibleState.theme === 'dark' ? 'light' : 'dark';
114:       this.applyTheme(next);
