120:         pill.className = `status-pill ${online ? 'online' : 'offline'}`;
121:         pill.innerHTML = online 
122:           ? '<span class="status-dot">●</span> Online' 
123:           : '<span class="status-dot">○</span> Offline Mode';
124:       }
125:     }
