from pathlib import Path

# 1. Update bible-navigation.js
nav_path = Path("frontend/bible/bible-navigation.js")
nav_text = nav_path.read_text(encoding="utf-8")

nav_target = """    goToPassage(bookSlug, chapter, verse = null) {
      const b = this.books.find(item => item.slug === bookSlug || item.name.toLowerCase() === bookSlug.toLowerCase());
      if (b) {
        this.currentBook = b;
        this.currentChapter = Math.min(b.chaptersCount, Math.max(1, parseInt(chapter, 10)));
        this.targetVerse = verse ? parseInt(verse, 10) : null;
        this.updateHash();
        this.triggerChange();
      }
    }"""

nav_replacement = """    setVerse(verseNum) {
      this.targetVerse = verseNum ? parseInt(verseNum, 10) : null;
      this.updateHash();
      if (this.onPassageChanged && this.currentBook) {
        this.onPassageChanged({
          book: this.currentBook,
          chapter: this.currentChapter,
          translation: this.currentTranslation,
          parallelMode: this.parallelMode,
          targetVerse: this.targetVerse,
          verseOnly: true
        });
      }
    }

    goToPassage(bookSlug, chapter, verse = null) {
      const b = this.books.find(item => item.slug === bookSlug || item.name.toLowerCase() === bookSlug.toLowerCase());
      if (b) {
        this.currentBook = b;
        this.currentChapter = Math.min(b.chaptersCount, Math.max(1, parseInt(chapter, 10)));
        this.targetVerse = verse ? parseInt(verse, 10) : null;
        this.updateHash();
        this.triggerChange();
      }
    }"""

if nav_target.replace("\r\n", "\n") in nav_text.replace("\r\n", "\n"):
    # Normalize line endings
    nav_text_norm = nav_text.replace("\r\n", "\n")
    nav_text_norm = nav_text_norm.replace(nav_target.replace("\r\n", "\n"), nav_replacement.replace("\r\n", "\n"), 1)
    nav_path.write_text(nav_text_norm, encoding="utf-8")
    print("bible-navigation.js updated")
else:
    print("Target not found in bible-navigation.js")


# 2. Update bible-reader.js
reader_path = Path("frontend/bible/bible-reader.js")
reader_text = reader_path.read_text(encoding="utf-8")

reader_target = """    bindVerseActions(book, chapter, translation, verses) {"""

reader_replacement = """    highlightAndScrollVerse(verseNum) {
      if (!this.container) return;

      // Remove existing highlight
      this.container.querySelectorAll('.verse-highlighted').forEach(el => {
        el.classList.remove('verse-highlighted');
      });

      this.highlightedVerse = verseNum ? parseInt(verseNum, 10) : null;

      if (this.highlightedVerse) {
        const el = document.getElementById(`verse-${this.highlightedVerse}`);
        if (el) {
          el.classList.add('verse-highlighted');
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
