      for (let i = 1; i <= versesCount; i++) {
        const opt = document.createElement('option');
        opt.value = i.toString();
        opt.textContent = i.toString();
        if (selNum === i) {
          opt.selected = true;
        }
        select.appendChild(opt);
      }
    }

"""

app_text = app_text[:idx_start] + new_populate + app_text[idx_end:]
